/*--------------------------------------------------------------------------------------------------
 * File: benchmark.cpp
 *
 * Description: Times evaluation five ways: LODE's reference evaluator, its interpreter one point
 *              at a time and in batches, C++ code generated by LODE, and hand-written C++. The
 *              functions are a chemistry right-hand side and Jacobian, a larger reaction network,
 *              and quadratic triangle shape functions. Build with -DLODE_BUILD_BENCHMARKS=ON in
 *              Release mode.
 *------------------------------------------------------------------------------------------------*/
#include <chrono>
#include <cstddef>
#include <cstdio>
#include <functional>
#include <map>
#include <span>
#include <string>
#include <vector>

#include "benchmark_functions.hpp"
#include "benchmark_generated.hpp"
#include "lode/lode.hpp"

namespace
{
    using lode::Expr;
    using lode::Function;
    using Clock     = std::chrono::steady_clock;
    using PointCode = std::function<void(double const*, double*)>;

    // Result accumulated from every evaluation, so the compiler cannot skip the work
    volatile double sink = 0.0;


   /*-----------------------------------------------------------------------------------------------
    * double time_per_point(std::function<void()> const& work, std::size_t points)
    *
    * Nanoseconds per point: runs work (which evaluates `points` points) repeatedly for at least
    * 0.2 seconds and divides.
    *---------------------------------------------------------------------------------------------*/
    double time_per_point(std::function<void()> const& work, std::size_t points)
    {
        work();
        std::size_t repeats = 0;
        Clock::time_point start = Clock::now();
        Clock::duration   elapsed{};
        while (elapsed < std::chrono::milliseconds(200))
        {
            work();
            ++repeats;
            elapsed = Clock::now() - start;
        }
        double nanoseconds = std::chrono::duration<double, std::nano>(elapsed).count();
        return nanoseconds / static_cast<double>(repeats * points);
    }


   /*-----------------------------------------------------------------------------------------------
    * void report(lode::bench::BenchmarkFunction const& b, PointCode const& generated,
    *             PointCode const& by_hand)
    *
    * Times one function and prints a row of the table. The generated and hand-written code are
    * called the same way (through std::function, one point per call), so they compare fairly.
    *---------------------------------------------------------------------------------------------*/
    void report(lode::bench::BenchmarkFunction const& b, PointCode const& generated,
                PointCode const& by_hand)
    {
        Function const&   function = b.function;
        std::size_t const POINTS   = 1024;
        std::size_t const n_in     = function.input_size();
        std::size_t const n_out    = function.size();

        // Many copies of the point, slightly varied
        std::vector<double> inputs(POINTS * n_in);
        for (std::size_t p = 0; p < POINTS; ++p)
            for (std::size_t i = 0; i < n_in; ++i)
                inputs[p * n_in + i] = b.point[i] * (1.0 + 1e-6 * static_cast<double>(p));
        std::vector<double> outputs(POINTS * n_out);

        // Reference: the tree-walking evaluator, on a few points (it is slow)
        std::size_t const FEW = 16;
        lode::Values<double> values;
        for (std::size_t i = 0; i < n_in; ++i) values.emplace_back(function.domain()[i], 0.0);
        double reference = time_per_point([&]()
        {
            for (std::size_t p = 0; p < FEW; ++p)
            {
                for (std::size_t i = 0; i < n_in; ++i) values[i].second = inputs[p * n_in + i];
                for (Expr const& output : function.outputs())
                    sink = sink + lode::evaluate(output, values);
            }
        }, FEW);

        double single = time_per_point([&]()
        {
            for (std::size_t p = 0; p < POINTS; ++p)
            {
                std::span<double const> in(inputs.data() + p * n_in, n_in);
                std::span<double>       out(outputs.data() + p * n_out, n_out);
                function.evaluate(in, out);
            }
            sink = sink + outputs.back();
        }, POINTS);

        double batch = time_per_point([&]()
        {
            function.evaluate_batch(inputs, outputs);
            sink = sink + outputs.back();
        }, POINTS);

        auto time_code = [&](PointCode const& code)
        {
            return time_per_point([&]()
            {
                for (std::size_t p = 0; p < POINTS; ++p)
                    code(inputs.data() + p * n_in, outputs.data() + p * n_out);
                sink = sink + outputs.back();
            }, POINTS);
        };
        double from_code = time_code(generated);

        std::printf("%-32s %6zu %11.1f %9.1f %8.1f %10.1f", b.label.c_str(),
                    function.instruction_count(), reference, single, batch, from_code);
        if (by_hand) std::printf(" %8.1f", time_code(by_hand));
        std::printf("\n");
    }
}


int main()
{
    // Generated code, by name
    std::map<std::string, PointCode> generated{
        {"robertson_rhs", [](double const* in, double* out) {robertson_rhs(in, out);}},
        {"robertson_jacobian", [](double const* in, double* out) {robertson_jacobian(in, out);}},
        {"network_rhs", [](double const* in, double* out) {network_rhs(in, out);}},
        {"network_jacobian", [](double const* in, double* out) {network_jacobian(in, out);}},
        {"triangle_shape", [](double const* in, double* out) {triangle_shape(in, out);}},
        {"triangle_gradients", [](double const* in, double* out) {triangle_gradients(in, out);}}};

    // Hand-written code, where there is some
    std::map<std::string, PointCode> by_hand{
        {"robertson_rhs", [](double const* y, double* f)
        {
            f[0] = -0.04 * y[0] + 1e4 * y[1] * y[2];
            f[1] = 0.04 * y[0] - 1e4 * y[1] * y[2] - 3e7 * y[1] * y[1];
            f[2] = 3e7 * y[1] * y[1];
        }},
        {"robertson_jacobian", [](double const* y, double* j)
        {
            j[0] = -0.04; j[1] = 1e4 * y[2];               j[2] = 1e4 * y[1];
            j[3] = 0.04;  j[4] = -1e4 * y[2] - 6e7 * y[1]; j[5] = -1e4 * y[1];
            j[6] = 0.0;   j[7] = 6e7 * y[1];               j[8] = 0.0;
        }},
        {"triangle_shape", [](double const* p, double* n)
        {
            double a = 1.0 - p[0] - p[1];
            double b = p[0];
            double c = p[1];
            n[0] = a * (2.0 * a - 1.0); n[1] = b * (2.0 * b - 1.0); n[2] = c * (2.0 * c - 1.0);
            n[3] = 4.0 * a * b;         n[4] = 4.0 * b * c;         n[5] = 4.0 * c * a;
        }},
        {"triangle_gradients", [](double const* p, double* g)
        {
            double a = 1.0 - p[0] - p[1];
            double b = p[0];
            double c = p[1];
            g[0]  = 1.0 - 4.0 * a;  g[1]  = 1.0 - 4.0 * a;
            g[2]  = 4.0 * b - 1.0;  g[3]  = 0.0;
            g[4]  = 0.0;            g[5]  = 4.0 * c - 1.0;
            g[6]  = 4.0 * (a - b);  g[7]  = -4.0 * b;
            g[8]  = 4.0 * c;        g[9]  = 4.0 * b;
            g[10] = -4.0 * c;       g[11] = 4.0 * (a - c);
        }}};

    std::printf("Nanoseconds per point (one evaluation of every output)\n\n");
    std::printf("%-32s %6s %11s %9s %8s %10s %8s\n", "", "instr", "reference", "compiled", "batch",
                "generated", "by hand");
    for (lode::bench::BenchmarkFunction const& b : lode::bench::benchmark_functions())
    {
        auto hand = by_hand.find(b.name);
        report(b, generated.at(b.name), hand == by_hand.end() ? PointCode{} : hand->second);
    }

    return sink == 12345.0 ? 1 : 0;
}
